import base64, json, math, time
import numpy as np, torch
import os as _osx; _osx.system("python -m pip uninstall -y -q torchao 2>/dev/null")
from transformers import AutoTokenizer, AutoModelForCausalLM
MOUNT="/kaggle/input/models/qwen-lm/qwen2.5/transformers/0.5b-instruct/1"
SPR=[__import__("json").loads(x) for x in base64.b64decode("").decode().splitlines() if x.strip()]
SUM=[__import__("json").loads(x) for x in base64.b64decode("").decode().splitlines() if x.strip()]
PROBES={"spring": ["窗花还没剪，柳笛先响了", "灶糖粘住了小孩的门牙", "灯影里的老鼠娶亲队伍排到了巷尾", "红包压在枕头下睡着了", "鞭炮屑给街道下了一场红雪", "屠苏酒暖了半张圆桌", "门神换了新的，旧对联还舍不得走", "元宵的兔子灯游进了星河"], "summer": ["冰棍拆穿了一个正午", "蝉把树的午后锯成了两段", "竹席上躺着一个流汗的黎明", "西瓜中间那一勺是夏天的王", "雷阵雨没收了所有人的晾衣绳", "蒲扇摇不动的热，交给了井水", "萤火虫在替夜空打草稿", "短袖和蚊子达成了和解"], "noir": ["茶凉透之前，线人不会开口", "码头的账本用血写了一半就干了", "白手套摸过的档案都烫手", "天台的风替两个人保守秘密", "香堂的规矩大过天亮", "警车掠过时，整条街的麻将声停了半秒", "二五仔的赏金买不来一个安稳觉", "卧底的证件照里住着两个人"]}; NOIR=["江湖讲的是一个义字，办的是见不得光的事。", "大哥说过，上了这条船就没有下船的码头。", "货从北边来走南边的水，中间不能见官。", "背叛过一次的牌子，挂二心旗。", "场子乱了，先按住刀再讲理。", "规矩是老祖宗立的，动规矩的人先动刀。", "堂口点灯，见者有份。", "兄弟归兄弟，账还是要算清楚。"]
dev="cuda"; tok=AutoTokenizer.from_pretrained(MOUNT)
model=AutoModelForCausalLM.from_pretrained(MOUNT,dtype=torch.float16).eval().to(dev)
def emb(t):
    e=tok(t,add_special_tokens=False,return_tensors="pt").to(dev)
    with torch.no_grad(): h=model.model(**e).last_hidden_state[0].float().cpu().numpy()
    return h.mean(0)
texts=lambda c:[m["messages"][0]["content"]+" "+m["messages"][1]["content"] for m in c]
DOM={"spring":texts(SPR),"summer":texts(SUM),"noir":NOIR}
allv=[emb(x) for d in DOM.values() for x in d]+[emb(s) for ss in PROBES.values() for s in ss]
MU=np.vstack(allv).mean(0)
def u(v):
    w=v-MU; return w/(np.linalg.norm(w)+1e-9)
names=list(DOM); cents={"@K@":0}
for nm in names:
    vs=np.stack([u(emb(x)) for x in DOM[nm]]); c=vs.mean(0); cents[nm]=c/(np.linalg.norm(c)+1e-9)
# v5 歧义探针池: 表面形世界无关, 读法由语境定 —— 女儿国探针恒等式的操作化 (旧域专属池=自指纹压倒世界, 见 READOUTS.md)
AMB=["那件事后来怎么样了","门外的声音停了很久","他等到天亮才走","桌上放着两杯还热的茶","谁把灯关了","那年今日又下起了雨","她把信折了三折收进抽屉","巷子里传来脚步声","窗上的白雾擦了又出来","该来的总会来","一半留着，一半不留","别回头","今年比去年冷","人走了，位子还温着","话到嘴边又咽回去"]
pnames=AMB
pvec=[u(emb(p)) for p in pnames]
T=0.07
O=np.zeros((len(pnames),3,3))
# v4 信道重铸: P(o|s,j) 必须随真态 s 变化 —— 探针 j 在世界 s 的语境里被照明 (同探针异空间照明不同)
ctx={nm:DOM[nm][0]+"\n"+DOM[nm][1] for nm in names}
for j,p in enumerate(pnames):
    for si,nm in enumerate(names):
        v=u(emb(ctx[nm]+"\n"+p))
        sc=np.array([float(v@cents[names[k]]) for k in range(3)])/T
        pr=np.exp(sc-sc.max()); pr/=pr.sum(); O[j,si]=0.95*pr+0.05/3
rng=np.random.default_rng(13)
def entropy(q): return -sum(x*math.log(x+1e-12) for x in q)
def run(policy):
    out=[]
    for s in range(3):
        for _ in range(10):
            a=np.ones(3); used=set(); t=0
            for t in range(12):
                post=a/a.sum()
                if post.max()>0.9: t-=1; break
                if policy=="meie":
                    best=(-1e9,-1)
                    cand=list(range(len(pnames))); rng.shuffle(cand)   # 破平随机: 防恒选 j=0 的世界-0 系统偏置
                    for j in cand:
                        if j in used: continue
                        EH=0.0
                        for o in range(3):
                            p_o=sum(post[ss]*O[j,ss,o] for ss in range(3))
                            if p_o<=0: continue
                            a2=a*O[j,:,o]; a2/=a2.sum()
                            EH+=p_o*entropy(a2/a2.sum())
                        gain=-float(EH)
                        if gain>best[0]: best=(gain,j)
                    j=best[1]
                else:
                    j=int(rng.integers(len(pnames)))
                used.add(j)
                o=int(rng.choice(3,p=O[j,s]/O[j,s].sum()))
                a=a*O[j,:,o]; a/=a.sum()   # v4: 贝叶斯乘性更新 (旧 a[o]+=1 硬计数在 12 步封顶内 max post≤0.867, 0.9 阈值不可达 → 11/11 封顶伪影)
            out.append(t)
    return out
me=run("meie"); rd=run("random")
cal=0; tot=0
for j in range(len(pnames)):
    pr=O[j].mean(0)
    for s in range(3):
        o=int(rng.choice(3,p=O[j,s]/O[j,s].sum())); tot+=1; cal+=int(np.argmax(pr)==o)
res={"exp":"25-belief-drill","mean_meie":round(float(np.mean(me)),2),"mean_random":round(float(np.mean(rd)),2),
 "meie_le_random":int(sum(1 for x,y in zip(me,rd) if x<y)),"calib_diag":round(cal/tot,3),
 "steps_meie":me,"steps_random":rd,"j1_pass":bool(np.mean(me)<np.mean(rd)),
 "note":"v5: 歧义探针池 15 句 (表面形世界无关读法由语境定); 语境依赖信道; 乘性贝叶斯; 破平随机; 收敛=max post>0.9; 12 步封顶; J1/J2 不动"}
json.dump(res,open("/kaggle/working/report_exp25.json","w"))
print("REPORT_LINE",base64.b64encode(json.dumps(res).encode()).decode())
